/* Thread A */
pthread_mutex_lock(&lock1);   /* Step 1: A now holds lock1 */
pthread_mutex_lock(&lock2);   /* Step 3: A blocks here if B already holds lock2 */
do_work();
pthread_mutex_unlock(&lock2);
pthread_mutex_unlock(&lock1);

/* Thread B */
pthread_mutex_lock(&lock2);   /* Step 2: B now holds lock2 */
pthread_mutex_lock(&lock1);   /* Step 4: B blocks here if A already holds lock1 */
do_work();
pthread_mutex_unlock(&lock1);
pthread_mutex_unlock(&lock2);

/* If steps 1 and 2 both happen before either thread reaches its
   second lock call, steps 3 and 4 block forever. Step 5: deadlock. */

